import React, { useState, useMemo } from 'react';
import { useManagerStore } from '../../../store/managerStore';
import { safeParseDate } from '../../../utils/dateHelpers';

export default function PartsTransactionsList({ user, onManualIssue }) {
  const parts = useManagerStore((state) => state.parts || []);
  const machines = useManagerStore((state) => state.machines || []);
  const tickets = useManagerStore(state => state.tickets || []);
  const plannedServices = useManagerStore(state => state.plannedServices || []);
  const partTransactions = useManagerStore((state) => state.partTransactions || []);

  
  const getMachineName = (tx) => {
    if (tx.machineId) {
      const m = machines.find(mac => mac.id === tx.machineId);
      if (m) return m.name;
    }
    if (tx.referenceId) {
      if (tx.type === 'issue_adhoc') {
        const t = tickets.find(tic => tic.id === tx.referenceId);
        if (t && t.machineId) {
          const m = machines.find(mac => mac.id === t.machineId);
          if (m) return m.name;
        }
      } else if (tx.type === 'issue_planned') {
        const s = plannedServices.find(srv => srv.id === tx.referenceId);
        if (s && s.machineId) {
          const m = machines.find(mac => mac.id === s.machineId);
          if (m) return m.name;
        }
      }
    }
    return tx.machineName || '';
  };

  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 30;

  const filteredTransactions = useMemo(() => {
    return partTransactions
      .filter((tx) => {
        // Type filter
        if (typeFilter !== 'all' && tx.type !== typeFilter) return false;
        
        // Date filter
        const txDate = safeParseDate(tx.date);
        if (dateFrom && txDate) {
          const from = new Date(dateFrom);
          if (txDate < from) return false;
        }
        if (dateTo && txDate) {
          const to = new Date(dateTo);
          to.setHours(23, 59, 59, 999);
          if (txDate > to) return false;
        }

        // Search text
        if (search.trim()) {
          const q = search.toLowerCase();
          const part = parts.find((p) => p.id === tx.partId);
          const partName = part?.name?.toLowerCase() || '';
          const machineName = getMachineName(tx).toLowerCase();
          const userName = tx.user?.toLowerCase() || '';
          
          if (!partName.includes(q) && !machineName.includes(q) && !userName.includes(q)) {
            return false;
          }
        }

        return true;
      })
      .sort((a, b) => {
        const dateA = safeParseDate(a.date);
        const dateB = safeParseDate(b.date);
        return (dateB?.getTime() || 0) - (dateA?.getTime() || 0);
      });
  }, [partTransactions, typeFilter, dateFrom, dateTo, search, parts, machines]);

  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);
  const currentData = filteredTransactions.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const getTypeName = (type) => {
    switch(type) {
      case 'receive': return 'Przyjęcie';
      case 'issue_planned': return 'Wydanie (Serwis)';
      case 'issue_adhoc': return 'Wydanie Ręczne';
      case 'return': return 'Zwrot';
      default: return type;
    }
  };

  const getTypeStyle = (type) => {
    if (type === 'receive' || type === 'return') {
      return 'text-green-600 bg-green-50';
    }
    return 'text-red-600 bg-red-50';
  };

  const getQtyStyle = (type) => {
    if (type === 'receive' || type === 'return') {
      return 'text-green-600 font-semibold';
    }
    return 'text-red-600 font-semibold';
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col h-full">
      <div className="p-4 border-b border-gray-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
          <i className="ph ph-list-numbers text-blue-500"></i>
          Historia operacji magazynowych
        </h2>
        <button
          onClick={onManualIssue}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center gap-2 transition-colors font-medium text-sm"
        >
          <i className="ph ph-hand-coins"></i>
          Dodaj ręczne wydanie
        </button>
      </div>

      <div className="p-4 grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-50 border-b border-gray-100">
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Typ operacji</label>
          <select 
            value={typeFilter} 
            onChange={(e) => { setTypeFilter(e.target.value); setCurrentPage(1); }}
            className="w-full rounded-lg border-gray-300 border p-2 text-sm focus:ring-2 focus:ring-blue-500"
          >
            <option value="all">Wszystkie</option>
            <option value="receive">Przyjęcie</option>
            <option value="issue_planned">Wydanie (Serwis)</option>
            <option value="issue_adhoc">Wydanie Ręczne</option>
            <option value="return">Zwrot</option>
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Wyszukaj</label>
          <div className="relative">
            <i className="ph ph-magnifying-glass absolute left-3 top-2.5 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Część, maszyna, użytkownik..." 
              value={search}
              onChange={(e) => { setSearch(e.target.value); setCurrentPage(1); }}
              className="w-full rounded-lg border-gray-300 border p-2 pl-9 text-sm focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Od daty</label>
          <input 
            type="date" 
            value={dateFrom}
            onChange={(e) => { setDateFrom(e.target.value); setCurrentPage(1); }}
            className="w-full rounded-lg border-gray-300 border p-2 text-sm focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Do daty</label>
          <input 
            type="date" 
            value={dateTo}
            onChange={(e) => { setDateTo(e.target.value); setCurrentPage(1); }}
            className="w-full rounded-lg border-gray-300 border p-2 text-sm focus:ring-2 focus:ring-blue-500"
          />
        </div>
      </div>

      <div className="overflow-x-auto flex-1">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-white border-b border-gray-100 text-gray-500 text-xs uppercase tracking-wider">
              <th className="p-3 font-medium">Data</th>
              <th className="p-3 font-medium">Typ</th>
              <th className="p-3 font-medium">Część</th>
              <th className="p-3 font-medium text-right">Ilość</th>
              <th className="p-3 font-medium text-right">Koszt (PLN)</th>
              <th className="p-3 font-medium">Maszyna</th>
              <th className="p-3 font-medium">Użytkownik</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 text-sm">
            {currentData.length === 0 ? (
              <tr>
                <td colSpan="7" className="p-8 text-center text-gray-500">
                  Brak transakcji spełniających kryteria.
                </td>
              </tr>
            ) : (
              currentData.map((tx) => {
                const part = parts.find(p => p.id === tx.partId);
                const machine = machines.find(m => m.id === tx.machineId);
                const isPositive = tx.type === 'receive' || tx.type === 'return';
                
                return (
                  <tr key={tx.id || Math.random().toString()} className="hover:bg-gray-50 transition-colors">
                    <td className="p-3 text-gray-600 whitespace-nowrap">
                      {safeParseDate(tx.date)?.toLocaleString('pl-PL')}
                    </td>
                    <td className="p-3">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getTypeStyle(tx.type)}`}>
                        {getTypeName(tx.type)}
                      </span>
                    </td>
                    <td className="p-3 font-medium text-gray-800">
                      {part?.name || tx.partName || 'Nieznana część'}
                    </td>
                    <td className={`p-3 text-right ${getQtyStyle(tx.type)}`}>
                      {isPositive ? '+' : '-'}{tx.quantity}
                    </td>
                    <td className="p-3 text-right text-gray-600">
                      {tx.totalCost != null ? tx.totalCost.toFixed(2) : '-'}
                    </td>
                    <td className="p-3 text-gray-600">
                      {machine?.name || tx.machineName || '-'}
                    </td>
                    <td className="p-3 text-gray-600">
                      {tx.user || '-'}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="p-4 border-t border-gray-100 flex items-center justify-between bg-white rounded-b-xl">
          <p className="text-sm text-gray-500">
            Strona <span className="font-medium text-gray-900">{currentPage}</span> z <span className="font-medium text-gray-900">{totalPages}</span>
            <span className="ml-2 text-gray-400">({filteredTransactions.length} wpisów)</span>
          </p>
          <div className="flex gap-2">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Poprzednia
            </button>
            <button
              onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Następna
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
