import React, { useState, useMemo } from 'react';
import { useManagerStore } from '../../../store/managerStore';
import { QRCodeCanvas } from 'qrcode.react';
import { getCurrentTenant } from '../../../utils/tenantHelper';
import { safeParseDate } from '../../../utils/dateHelpers';
import PartTransactionModal from './PartTransactionModal';

export default function PartDetails({ part, onBack, user, onEdit }) {
  const [txMode, setTxMode] = useState(null);
  const transactions = useManagerStore(state => state.partTransactions || []);
  const plannedServices = useManagerStore(state => state.plannedServices || []);
  const tickets = useManagerStore(state => state.tickets || []);
  const machines = useManagerStore(state => state.machines || []);

  const tenantId = getCurrentTenant();
  const qrValue = `tenant=${tenantId}&part=${part.id}`;

  const partTxs = useMemo(() => {
    return transactions
      .filter(tx => tx.partId === part.id)
      .sort((a, b) => new Date(b.date) - new Date(a.date));
  }, [transactions, part.id]);

  const plannedUsage = useMemo(() => {
    return plannedServices.filter(s => 
      s.status !== 'completed' && 
      s.requiredParts && 
      s.requiredParts.some(rp => rp.partId === part.id)
    ).sort((a, b) => new Date(a.nextDate) - new Date(b.nextDate));
  }, [plannedServices, part.id]);

  const reservedQty = plannedUsage.reduce((sum, s) => {
    const req = s.requiredParts.find(rp => rp.partId === part.id);
    return sum + (req ? Number(req.quantity || 0) : 0);
  }, 0);

  const available = Number(part.stock) - reservedQty;
  const isLow = available < Number(part.minStock);
  const isOut = available <= 0;

  // Obliczenia wartości zapasów
  const batches = part.batches || [];
  const totalValue = batches.reduce((sum, b) => sum + (Number(b.qty) * Number(b.price || 0)), 0);
  const avgPrice = part.stock > 0 ? (totalValue / part.stock) : (part.unitPrice || 0);
  
  // Sortowanie partii po dacie ważności (rosnąco, null na końcu)
  const sortedBatches = [...batches].sort((a, b) => {
    if (!a.expirationDate) return 1;
    if (!b.expirationDate) return -1;
    return new Date(a.expirationDate) - new Date(b.expirationDate);
  });

  return (
    <div className="w-full space-y-4 pb-20">
      {/* NAGŁÓWEK */}
      <div className="p-2 md:p-4 border-b border-gray-200 bg-white sticky top-0 z-20 flex flex-wrap justify-between items-center gap-2 shadow-sm rounded-xl">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 md:px-5 md:py-2.5 text-xs md:text-base rounded-md md:rounded-lg font-bold shadow-md transition-all">
            <i className="ph ph-arrow-left text-lg"></i> Powrót do rejestru
          </button>
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tight">{part.name}</h2>
            <p className="text-xs sm:text-sm font-bold text-slate-400 mt-1 uppercase tracking-widest">KOD: {part.code || '-'}</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button onClick={() => setTxMode('receive')} className="bg-emerald-600 text-white hover:bg-emerald-700 px-3 py-1.5 md:px-5 md:py-2.5 rounded-md md:rounded-lg font-bold shadow-md transition-all flex items-center gap-2 text-xs md:text-base">
            <i className="ph ph-plus-circle text-lg"></i> Dostawa
          </button>
          <button onClick={() => setTxMode('issue')} className="bg-red-500 text-white hover:bg-red-600 px-3 py-1.5 md:px-5 md:py-2.5 rounded-md md:rounded-lg font-bold shadow-md transition-all flex items-center gap-2 text-xs md:text-base">
            <i className="ph ph-minus-circle text-lg"></i> Korekta / Wydanie
          </button>
          <button onClick={onEdit} className="bg-slate-100 text-slate-700 border border-slate-300 hover:bg-slate-200 px-3 py-1.5 md:px-5 md:py-2.5 rounded-md md:rounded-lg font-bold shadow-sm transition-all flex items-center gap-2 text-xs md:text-base">
            <i className="ph ph-pencil-simple text-lg"></i> Edytuj
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* INFO */}
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Informacje Ogólne</h3>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-6">
              <div>
                <div className="text-[10px] font-bold text-slate-400 uppercase">Lokalizacja</div>
                <div className="font-semibold text-slate-800 text-sm">{part.building ? part.building + ' / ' : ''}{part.location || 'Brak danych'}</div>
              </div>
                              <div>
                  <div className="text-[10px] font-bold text-slate-400 uppercase">Cena Jedn. (Średnia)</div>
                  <div className="font-semibold text-slate-800 text-sm">{avgPrice.toFixed(2)} PLN</div>
                </div>
                <div>
                  <div className="text-[10px] font-bold text-slate-400 uppercase text-blue-500">Wartość Zapasu</div>
                  <div className="font-black text-blue-600 text-sm">{totalValue.toFixed(2)} PLN</div>
                </div>
                                <div>
                  <div className="text-[10px] font-bold text-slate-400 uppercase">Data wprow.</div>
                  <div className="font-semibold text-slate-800 text-sm">{part.createdAt ? safeParseDate(part.createdAt.toDate ? part.createdAt.toDate() : part.createdAt).toLocaleDateString('pl-PL') : '-'}</div>
                </div>
                <div>
                  <div className="text-[10px] font-bold text-slate-400 uppercase">Ost. edycja</div>
                  <div className="font-semibold text-slate-800 text-sm">{part.updatedAt ? safeParseDate(part.updatedAt.toDate ? part.updatedAt.toDate() : part.updatedAt).toLocaleDateString('pl-PL') : '-'}</div>
                </div>
            
                          </div>
              <div className="mt-6 pt-4 border-t border-slate-50">
                <div className="text-[10px] font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">
                  <i className="ph ph-stack text-lg"></i>
                  Dostępne Partie na Magazynie (FIFO)
                </div>
                {sortedBatches.length === 0 ? (
                  <div className="text-xs text-slate-400 italic">Brak partii na stanie.</div>
                ) : (
                  <div className="space-y-2">
                    {sortedBatches.map((b, i) => (
                      <div key={i} className="flex justify-between items-center p-2 rounded-lg bg-slate-50 border border-slate-100 text-xs">
                        <div>
                          <span className="font-black text-slate-700">{b.qty} szt.</span>
                          <span className="text-slate-400 ml-2">po {Number(b.price || 0).toFixed(2)} PLN</span>
                        </div>
                        <div className={`font-bold ${b.expirationDate ? (new Date(b.expirationDate) < new Date() ? 'text-red-500' : 'text-orange-500') : 'text-slate-400'}`}>
                          {b.expirationDate ? `Ważne: ${new Date(b.expirationDate).toLocaleDateString('pl-PL')}` : 'Brak daty ważności'}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="mt-6 pt-4 border-t border-slate-50">
                <div className="text-[10px] font-bold text-slate-400 uppercase mb-2">Kompatybilność Maszynowa</div>
              <div className="flex flex-wrap gap-2">
                {part.compatibleMachines && part.compatibleMachines.length > 0 ? (
                  part.compatibleMachines.map(mid => {
                    const m = machines.find(mac => mac.id === mid);
                    return <span key={mid} className="bg-slate-50 border border-slate-100 px-3 py-1 rounded-lg text-xs font-bold text-slate-600">{m ? m.name : 'Nieznana maszyna'}</span>;
                  })
                ) : (
                  <span className="text-xs text-slate-400 italic">Brak przypisanych maszyn</span>
                )}
              </div>
            </div>
          </div>

          {/* ZAPLANOWANE ZUŻYCIE */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="ph ph-calendar-check text-lg"></i>
              Zaplanowane Zużycie (Rezerwacje)
            </h3>
            {plannedUsage.length === 0 ? (
              <div className="text-center py-6 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                <i className="ph ph-check-circle text-2xl text-emerald-400 mb-2"></i>
                <p className="text-sm text-slate-500 font-medium">Brak nadchodzących serwisów wymagających tej części.</p>
              </div>
            ) : (
              <div className="space-y-3">
                {plannedUsage.map(s => {
                  const reqQty = s.requiredParts.find(rp => rp.partId === part.id)?.quantity || 0;
                  return (
                    <div key={s.id} className="flex justify-between items-center p-3 border border-slate-100 rounded-xl bg-slate-50">
                      <div>
                        <div className="font-bold text-slate-800 text-sm">{s.name}</div>
                        <div className="text-xs font-bold text-slate-400 mt-0.5">Planowane: {safeParseDate(s.nextDate).toLocaleDateString('pl-PL')}</div>
                      </div>
                      <div className="bg-orange-100 text-orange-700 px-3 py-1 rounded-lg font-black text-sm">
                        {reqQty} szt.
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* PRAWA KOLUMNA: STATUS & QR & HISTORIA */}
        <div className="space-y-4">
          
          {/* STAN */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col items-center text-center">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Stan Magazynowy</h3>
            
            <div className={`w-32 h-32 rounded-full border-[6px] flex flex-col items-center justify-center mb-4 ${isOut ? 'border-red-500 text-red-500' : isLow ? 'border-orange-500 text-orange-500' : 'border-emerald-500 text-emerald-500'}`}>
              <div className="text-4xl font-black leading-none">{available}</div>
              <div className="text-[10px] font-bold uppercase mt-1">Dostępne</div>
            </div>
            
            <div className="grid grid-cols-2 w-full gap-4 pt-4 border-t border-slate-50">
              <div>
                <div className="text-xs text-slate-400 font-bold uppercase">Fizycznie</div>
                <div className="text-lg font-black text-slate-700">{part.stock}</div>
              </div>
              <div>
                <div className="text-xs text-slate-400 font-bold uppercase">Zarezerw.</div>
                <div className="text-lg font-black text-orange-500">{reservedQty}</div>
              </div>
            </div>
            <div className="mt-3 w-full bg-slate-50 py-1.5 rounded-lg text-xs font-bold text-slate-500">
              Stan Minimalny: {part.minStock}
            </div>
          </div>

          {/* QR */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col items-center">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Kod QR Części</h3>
            <div className="bg-white p-3 rounded-2xl border-2 border-slate-100 shadow-sm">
              <QRCodeCanvas value={qrValue} size={140} level="H" />
            </div>
            <p className="text-[10px] text-slate-400 text-center mt-3 font-medium px-4">
              Naklej na pudełko/regał, aby szybko skanować wydania i przyjęcia.
            </p>
          </div>

          {/* AUDYT */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="ph ph-clock-counter-clockwise text-lg"></i>
              Historia Operacji
            </h3>
            {partTxs.length === 0 ? (
              <div className="text-xs text-slate-400 italic text-center py-2">Brak operacji.</div>
            ) : (
              <div className="space-y-3 max-h-[500px] overflow-y-auto pr-1">
                {partTxs.map(tx => {
                  const isAdd = tx.type === 'receive' || tx.type === 'return';
                  return (
                    <div key={tx.id} className="flex justify-between items-center text-xs border-b border-slate-50 pb-2 last:border-0 last:pb-0">
                      <div>
                        <div className="font-bold text-slate-700">
                          {tx.type === 'receive' ? 'Przyjęcie' : tx.type === 'issue_planned' ? 'Wydanie (Serwis)' : tx.type === 'issue_adhoc' ? 'Wydanie (Ręczne)' : 'Zwrot'}
                        </div>
                        <div className="text-slate-400 text-[10px] mt-0.5">
                          {safeParseDate(tx.date)?.toLocaleDateString('pl-PL')} • {tx.user}
                        </div>
                        {(() => {
                          if (tx.type !== 'issue_planned' && tx.type !== 'issue_adhoc') return null;
                          let mName = tx.machineName;
                          if (tx.machineId) {
                            const m = machines.find(mac => mac.id === tx.machineId);
                            if (m) mName = m.name;
                          } else if (tx.referenceId) {
                            if (tx.type === 'issue_adhoc') {
                              const t = tickets.find(tic => tic.id === tx.referenceId);
                              if (t && t.machineId) {
                                const m = machines.find(mac => mac.id === t.machineId);
                                if (m) mName = m.name;
                              }
                            } else if (tx.type === 'issue_planned') {
                              const s = plannedServices.find(srv => srv.id === tx.referenceId);
                              if (s && s.machineId) {
                                const m = machines.find(mac => mac.id === s.machineId);
                                if (m) mName = m.name;
                              }
                            }
                          }
                          if (!mName) return null;
                          return (
                            <div className="text-[10px] text-blue-500 font-semibold mt-0.5 flex items-center gap-1">
                              <i className="ph ph-gear text-xs"></i>
                              {mName}
                            </div>
                          );
                        })()}
                        {(tx.type === 'issue_planned' || tx.type === 'issue_adhoc') && tx.totalCost > 0 && (
                          <div className="text-[10px] text-slate-500 font-medium mt-0.5">
                            Koszt: {tx.totalCost.toFixed(2)} PLN
                          </div>
                        )}
                      </div>
                      <div className={`font-black ${isAdd ? 'text-emerald-500' : 'text-red-500'}`}>
                        {isAdd ? '+' : '-'}{Math.abs(tx.quantity)}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

        </div>
      </div>

      {txMode && (
        <PartTransactionModal part={part} mode={txMode} onClose={() => setTxMode(null)} user={user} />
      )}
    </div>
  );
}
